import {drawCityReward} from './reward-models.js?v=performing-arts-center-1';
import {REWARDS,rewardCondition,rewardProgress} from './rewards.js?v=performing-arts-center-1';
export function showRewards({city,dialog,close,setTool}){const c=city(),fmt=n=>'§'+n.toLocaleString();dialog('Rewards · gifts for your city',`<p>Fulfill each requirement for consecutive simulation months to receive an offer. Scenario events can also grant a reward before its normal requirements are met. Earned rewards remain available until you are ready to place them. You can have one of each; after demolition or destruction you can rebuild.</p>${Object.entries(REWARDS).map(([k,d])=>{const progress=rewardProgress(c,k),{earned,placed}=progress;return `<div class="milestone"><small>${placed?'PLACED':earned?'AVAILABLE TO PLACE':rewardCondition(c,k)?'REQUIREMENTS MET · KEEP IT UP':'WORKING TOWARD THIS'}</small><h3>${d.name}</h3><canvas id="rewardPreview-${k}" width="512" height="512" role="img" aria-label="${d.name} building preview" style="display:block;width:min(100%,280px);height:auto;margin:auto"></canvas><button data-reward-rotate="${k}" aria-label="Rotate ${d.name} preview">Rotate preview</button><p>${d.requirement}</p>${!earned?rewardChecklist(progress):''}<p>${progress.next}</p><p>${earned?`Earned in city month ${c.rewards.earned[k]}.`:`Progress: ${c.rewards.streaks[k]} / ${d.months} consecutive months.`}</p><p>${d.size} × ${d.size} level land · ${fmt(d.cost)} construction · ${fmt(d.upkeep)}/month upkeep. Needs electricity and a nearby road.</p><p>${k==='performingArts'?'An operating center provides 40 civic jobs, adds capacity for 48,000 residents, and improves nearby residential/commercial value and wellbeing. It produces modest local air and water pollution.':k==='medicalResearch'?'An operating center provides 135 civic jobs and improves nearby residential and commercial land value and resident wellbeing. It creates modest local air and water pollution; it does not replace hospital beds.':k==='countyCourthouse'?'An operating courthouse provides 135 civic jobs and reduces nearby crime by up to 30 points within 30 tiles. Workers need a route to the building.':k==='cityHall'?'An operating City Hall provides 36 civic jobs and improves nearby land value and resident wellbeing. Workers must be able to reach it.':k==='mayorHouse'?'An operating Mayor’s House adds capacity for 6,000 residents, provides four civic jobs, and improves nearby land value and happiness.':k==='stadium'?'An operating stadium provides 200 civic jobs, adds 20 residential demand and room for 125,000 residents. It benefits nearby commercial land value and wellbeing, but reduces residential land value and creates pollution and crime pressure.':'An operating university provides 500 civic jobs, adds 10 to the education target and 10 commercial demand, and improves nearby residential and commercial land value. It also creates local pollution and crime pressure; consider separation from homes and police coverage.'}</p><button data-reward="${k}" ${!earned||placed?'disabled':''}>Place ${d.name}</button></div>`;}).join('')}<p class="fine">University eligibility uses the original 105/150 education threshold, shown here as 70/100, and placement is free. New universities use the original 10 × 10 footprint. Stadiums use the original population requirement, construction price and 5 × 5 footprint. The original stadium aura threshold is normalized to this city’s approval scale. Reward effects and the remaining unlock rules still include reconstruction tuning. This is the first reward set; the original full reward and business-opportunity catalog remains unfinished.</p>`);const rotations={};for(const k of Object.keys(REWARDS)){rotations[k]=0;const canvas=document.getElementById('rewardPreview-'+k),ctx=canvas.getContext('2d');const draw=()=>{ctx.clearRect(0,0,512,512);drawCityReward(ctx,k,rotations[k],256,320,512);};document.querySelector('[data-reward-rotate="'+k+'"]').onclick=()=>{rotations[k]=(rotations[k]+1)%4;draw();};draw();}document.querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{setTool(b.dataset.reward);close();});}

export function rewardChecklist(progress){
 const number=n=>n.toLocaleString('en-US',{maximumFractionDigits:6});
 return `<table aria-label="Reward requirements"><thead><tr><th scope="col">Requirement</th><th scope="col">Current</th><th scope="col">Needed</th><th scope="col">Status</th></tr></thead><tbody>${progress.requirements.map(r=>`<tr><th scope="row">${r.label}</th><td>${r.money?'§':''}${number(r.current)}</td><td>${r.strict?'More than ':'At least '}${r.money?'§':''}${number(r.target)}</td><td>${r.met?'Met':'Missing'}</td></tr>`).join('')}</tbody></table>`;
}
